#!/usr/bin/env bash
# v0.5.2 build gate: fail if the Android manifest (gitignored, generated by expo prebuild) would ship
# without the mic permission. Every APK v0.4.4-v0.5.1 had RECORD_AUDIO tools:node="remove".
# Usage: scripts/check-apk-manifest.sh [path/to/app.apk]   (APK check needs aapt; ANDROID_HOME)
set -euo pipefail
cd "$(dirname "$0")/.."
M=baseline/mobile/android/app/src/main/AndroidManifest.xml
if [ -f "$M" ]; then
  grep -q 'android.permission.RECORD_AUDIO' "$M" || { echo "FAIL: $M lacks RECORD_AUDIO"; exit 1; }
  if grep 'android.permission.RECORD_AUDIO' "$M" | grep -q 'tools:node="remove"'; then echo "FAIL: $M removes RECORD_AUDIO"; exit 1; fi
  echo "OK: $M keeps RECORD_AUDIO"
else
  echo "SKIP: $M not generated here"
fi
if [ "${1:-}" ]; then
  A=$(ls "${ANDROID_HOME:-$HOME/android-sdk}"/build-tools/*/aapt | tail -1)
  "$A" dump permissions "$1" | grep -q "android.permission.RECORD_AUDIO" || { echo "FAIL: $1 has no RECORD_AUDIO"; exit 1; }
  echo "OK: $1 requests RECORD_AUDIO"
fi
